	RET

; runtime: unsigned division R0:R1 / R2:R3: the quotient in R0:R1, the remainder in R2:R3
__divu32:
	TEST  R1, R1
	JNZ   @slow
	TEST  R3, R3
	JNZ   @slow
	TEST  R2, R2
	JZ    @slow
	LD    R3, R0
	DIVU  R0, R2
	REMU  R3, R2
	LD    R2, R3
	LD    R3, #0
	RET
@slow:
	PUSH  R4
	PUSH  R5
	PUSH  R6
	LD    R4, #0
	LD    R5, #0
	LD    R6, #32
@loop:
	ADD   R0, R0
	ADC   R1, R1
	ADC   R4, R4
	ADC   R5, R5
	SUB   R4, R2
	SBC   R5, R3
	JNC   @set
	ADD   R4, R2
	ADC   R5, R3
	JMP   @next
@set:
	OR    R0, #1
@next:
	SUB   R6, #1
	JNZ   @loop
	LD    R2, R4
	LD    R3, R5
	POP   R6
	POP   R5
	POP   R4
	RET

